def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids)
    S = sorted(set(feats.stratum)); st = np.asarray(feats.stratum)
    Z = np.column_stack([np.ones(n)] + [(st == s).astype(float) for s in S[1:]])
    R = np.corrcoef(X, rowvar=False); R = np.nan_to_num(R)
    def fit(cols):
        A = np.column_stack([Z] + [c for c in cols]) if cols else Z
        b = np.zeros(A.shape[1])
        for _ in range(30):
            eta = np.clip(A @ b, -30, 30); mu = 1 / (1 + np.exp(-eta))
            w = mu * (1 - mu) + 1e-9
            H = A.T @ (A * w[:, None]) + 1e-6 * np.eye(A.shape[1])
            step = np.linalg.solve(H, A.T @ (y - mu)); b += step
            if np.abs(step).max() < 1e-7: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(A @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))
    col = lambda j: X[:, j] if not isinstance(j, tuple) else X[:, j[0]] * X[:, j[1]]
    def ll(sel): return fit([col(j) for j in sel])
    chi = lambda d: float(stats.chi2.sf(max(d, 0) * 2, 1))
    sel = []; base = ll(sel)
    for step in range(MAX_DRIVERS):
        alpha = (0.01 if step == 0 else 0.02) / p
        best = None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            v = ll(sel + [j])
            if best is None or v > best[1]: best = (j, v)
        if best is None or chi(best[1] - base) > alpha: break
        j, v = best
        clus = [k for k in range(p) if abs(R[j, k]) >= 0.6 and k not in sel]
        if len(clus) > 1:
            cand = []
            for c in clus:
                lc = ll(sel + [c])
                if lc < v - 3: continue
                if len(clus) > 2: g = -sum(abs(R[c, o]) for o in clus)
                else: g = sum(ll(sel + [c, o]) - lc for o in clus if o != c)
                cand.append((g, c, lc))
            g, j, v = min(cand)
        sel.append(j); base = v
    changed = True
    while changed and sel:
        changed = False
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if chi(base - ll(rest)) > 0.02 / p:
                sel = rest; base = ll(sel); changed = True; break
    prods = []
    m = p * (p + 1) // 2
    r0 = y - y.mean()
    sc = []
    for a in range(p):
        for b in range(a, p):
            q = X[:, a] * X[:, b]; q = q - q.mean()
            sc.append((abs(q @ r0) / (np.sqrt(q @ q) + 1e-9), a, b))
    sc.sort(reverse=True)
    for _, a, b in sc[:20]:
        mains = sorted(set(sel + [a, b]))
        l0 = ll(mains + prods); l1 = ll(mains + prods + [(a, b)])
        if chi(l1 - l0) < 0.001 / m and len(prods) < 2:
            prods.append((a, b))
            for k in (a, b):
                if k not in sel and len(sel) < MAX_DRIVERS: sel.append(k)
    drv = tuple(ids[j] for j in sel)[:MAX_DRIVERS]
    return Design(drivers=drv, columns=tuple(ids[j] for j in sel),
                  products=tuple((ids[a], ids[b]) for a, b in prods), loadings={})

